param([ValidateSet('x86','x64')][string]$CompileArchitecture)
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
$source = Join-Path $repoRoot '.deps/dxvk-remix'
if (-not $CompileArchitecture) {
  foreach ($arch in @('x86','x64')) {
    & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $PSCommandPath -CompileArchitecture $arch
    if ($LASTEXITCODE -ne 0) { throw "Asynchronous memory sampling failed: $arch" }
  }
  return
}
. (Join-Path $source 'bridge/build_common.ps1')
SetupVS -Platform $CompileArchitecture -VcVarsVer '14.29'
$testDir = Join-Path $repoRoot ".deps/memory-sampling-test/$CompileArchitecture"
New-Item -ItemType Directory -Force $testDir | Out-Null
Push-Location $testDir
try {
  & cl.exe /nologo /std:c++17 /EHsc /W4 /WX /O2 /MT /LD /D_WIN32_WINNT=0x0601 `
    "/I$source/bridge/src/client" "/I$repoRoot/tests" "$repoRoot/tests/memory_sampling_probe.cpp" `
    /Fe:memory-sampling-probe.dll /link "/DEF:$repoRoot/tests/memory_sampling_probe.def"
  if ($LASTEXITCODE -ne 0) { throw 'Memory sampling probe DLL compilation failed' }
  & cl.exe /nologo /std:c++17 /EHsc /W4 /WX /O2 /MT /D_WIN32_WINNT=0x0601 `
    "/I$repoRoot/tests" "$repoRoot/tests/memory_sampling_async.cpp" /Fe:memory-sampling-async.exe
  if ($LASTEXITCODE -ne 0) { throw 'Memory sampling native runner compilation failed' }
  & ./memory-sampling-async.exe (Join-Path $testDir 'memory-sampling-probe.dll')
  if ($LASTEXITCODE -ne 0) { throw "Memory sampling native regression failed: $LASTEXITCODE" }
} finally { Pop-Location }
